(()=>{
 const tab=document.createElement('button');tab.dataset.tab='analytics';tab.textContent='Visitors & activity';tab.setAttribute('aria-pressed','false');document.querySelector('.tabs').append(tab);
 const panel=document.createElement('section');panel.id='analytics';panel.hidden=true;
 panel.innerHTML='<h2>Visitors & activity</h2><p>Anonymous visitors who allow statistics. Cities are approximate network locations; VPNs and mobile networks can affect accuracy. Active means seen in the last five minutes.</p><div class="toolbar"><label>Period <select id="analytics-days"><option value="1">24 hours</option><option value="7">7 days</option><option value="30" selected>30 days</option></select></label><button id="analytics-refresh">Refresh activity</button></div><p id="analytics-status" role="status"></p><div class="stats" id="visitor-stats"></div><h3>Visitors around the world</h3><svg id="visitor-map" viewBox="0 0 1000 500" role="img" aria-label="World map of approximate visitor cities" style="width:100%;background:#edf3f5;border-radius:16px"><g id="map-land"></g><g id="map-dots"></g></svg><p id="map-status" class="muted">Loading map…</p><div style="overflow-x:auto"><table style="width:100%;text-align:left"><thead><tr><th>Country</th><th>City</th><th>Visitors</th><th>Active</th><th>Request signals</th></tr></thead><tbody id="visitor-cities"></tbody></table></div><h3>Booking activity</h3><div id="visitor-funnel"></div><p>Requests below come from the latest 1,000 saved appointment records loaded by this panel. Interest and WhatsApp clicks are activity signals, not payments. Payment reporting will be available when a payment provider is connected. Visitor counts are browser sessions, not verified individuals.</p><p>World boundaries: Natural Earth via world-atlas. No visitor data is sent to the map provider.</p>';
 document.querySelector('#dashboard').append(panel);
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));['appointments','treatments','content','analytics'].forEach(id=>document.getElementById(id).hidden=b.dataset.tab!==id);if(b===tab)refresh()});
 const byId=id=>document.getElementById(id),ns='http://www.w3.org/2000/svg';let busy=false;
 async function map(){try{const r=await fetch('https://cdn.jsdelivr.net/npm/world-atlas@2.0.2/countries-110m.json',{signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error();const t=await r.json();const arcs=t.arcs.map(arc=>{let x=0,y=0;return arc.map(p=>{x+=p[0];y+=p[1];return [(x*t.transform.scale[0]+t.transform.translate[0]+180)/360*1000,(90-(y*t.transform.scale[1]+t.transform.translate[1]))/180*500]})});
 for(const g of t.objects.countries.geometries){const rings=g.type==='Polygon'?[g.arcs]:g.arcs;const path=document.createElementNS(ns,'path');path.setAttribute('fill','#d7c5cc');path.setAttribute('stroke','#fffaf7');path.setAttribute('stroke-width','.5');path.setAttribute('d',rings.map(poly=>poly.map(ring=>{let pts=[];for(const a of ring){const part=a<0?[...arcs[~a]].reverse():arcs[a];pts.push(...(pts.length?part.slice(1):part))}return pts.map((p,i)=>(i?'L':'M')+p.join(',')).join('')+'Z'}).join('')).join(''));byId('map-land').append(path)}byId('map-status').textContent='Select a marker for its city. Unknown locations remain in the table.'}catch{byId('map-status').textContent='Map background could not load. City activity is still available in the table.'}}
 async function refresh(){if(busy||!session||document.querySelector('#dashboard').hidden)return;busy=true;byId('analytics-refresh').disabled=true;byId('analytics-status').textContent='Loading visitor activity…';try{
 const since=new Date(Date.now()-Number(byId('analytics-days').value)*86400000).toISOString();
 const rows=await db('bloom_visit_events?created_at=gte.'+encodeURIComponent(since)+'&select=*&order=created_at.desc&limit=10000');
 const unique=new Set(rows.map(r=>r.session_id)),active=new Set(rows.filter(r=>Date.parse(r.created_at)>Date.now()-300000).map(r=>r.session_id));
 const stat=(label,value)=>'<div class="stat"><span>'+esc(label)+'</span><b>'+value+'</b></div>';
 byId('visitor-stats').innerHTML=stat('Visitor sessions',unique.size)+stat('Active in last 5 minutes',active.size)+stat('Countries',new Set(rows.map(r=>r.country).filter(Boolean)).size)+stat('Payments','Not connected');
 const cities=new Map();for(const r of rows){const k=JSON.stringify([r.country,r.city]);if(!cities.has(k))cities.set(k,{...r,visitors:new Set(),active:new Set(),requests:0});const c=cities.get(k);c.visitors.add(r.session_id);if(active.has(r.session_id))c.active.add(r.session_id);if(r.kind==='booking_request')c.requests++}
 const country=c=>{try{return c?new Intl.DisplayNames(['en'],{type:'region'}).of(c):'Unknown'}catch{return c||'Unknown'}};
 byId('visitor-cities').innerHTML=[...cities.values()].sort((a,b)=>b.visitors.size-a.visitors.size).map(c=>'<tr><td>'+esc(country(c.country))+'</td><td>'+esc(c.city||'Unknown')+'</td><td>'+c.visitors.size+'</td><td>'+c.active.size+'</td><td>'+c.requests+'</td></tr>').join('')||'<tr><td colspan="5">No consenting visits recorded for this period.</td></tr>';
 byId('map-dots').replaceChildren();for(const c of cities.values()){if(c.latitude===null||c.longitude===null)continue;const dot=document.createElementNS(ns,'circle');dot.setAttribute('cx',(Number(c.longitude)+180)/360*1000);dot.setAttribute('cy',(90-Number(c.latitude))/180*500);dot.setAttribute('r',Math.min(14,4+Math.sqrt(c.visitors.size)));dot.setAttribute('fill','#723a50');dot.setAttribute('stroke','white');dot.setAttribute('tabindex','0');const title=document.createElementNS(ns,'title');title.textContent=(c.city||'Unknown')+', '+country(c.country)+': '+c.visitors.size+' sessions';dot.append(title);dot.setAttribute('aria-label',title.textContent);dot.onclick=()=>byId('map-status').textContent=title.textContent;dot.onfocus=dot.onclick;byId('map-dots').append(dot)}
 const recentRequests=requests.filter(r=>r.created_at>=since);byId('visitor-funnel').innerHTML='<div class="stats">'+stat('Treatment selections',rows.filter(r=>r.kind==='treatment').length)+stat('Appointment previews',rows.filter(r=>r.kind==='booking_preview').length)+stat('Saved requests',recentRequests.length)+stat('Confirmed requests',recentRequests.filter(r=>r.status==='confirmed').length)+stat('WhatsApp clicks',rows.filter(r=>r.kind==='whatsapp').length)+stat('Completed appointments',recentRequests.filter(r=>r.status==='completed').length)+'</div>';
 byId('analytics-status').textContent=rows.length===10000?'Showing the latest 10,000 events; narrow the period for complete counts.':'Updated '+new Date().toLocaleTimeString()+'. Auto-refreshes every minute while this tab is open.';
 }catch{byId('analytics-status').textContent='Visitor analytics is not connected yet, or your session has expired. Appointment management still works. Database setup and Vercel server credentials are required.';byId('visitor-stats').replaceChildren();byId('visitor-cities').replaceChildren();byId('map-dots').replaceChildren();byId('visitor-funnel').replaceChildren()}finally{busy=false;byId('analytics-refresh').disabled=false}}
 byId('analytics-refresh').onclick=refresh;byId('analytics-days').onchange=refresh;setInterval(()=>{if(!panel.hidden)refresh()},60000);map();
 document.querySelector('#logout').addEventListener('click',()=>{for(const id of ['visitor-stats','visitor-cities','map-dots','visitor-funnel'])byId(id).replaceChildren()});
})();
